def choose_move(observation):
    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [sign(dst[0] - src[0]), sign(dst[1] - src[1])]

    def nearest(src, items):
        best = None
        best_d = None
        for it in items or []:
            p = pos(it)
            if p is None:
                continue
            d = manhattan(src, p)
            if best is None or d < best_d or (d == best_d and (p[0], p[1]) < (best[0], best[1])):
                best = p
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    self_pos = pos(observation.get("self_position")) or (0, 0)
    opp_pos = pos(observation.get("opponent_position")) or self_pos
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = max(corners, key=lambda c: manhattan(c, opp_pos))
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        target = nearest(self_pos, targets)
        if target is None:
            target = opp_pos
        return step_toward(self_pos, target)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    target = nearest(self_pos, resources)
    if target is not None:
        return step_toward(self_pos, target)

    # Fallbacks: bias toward opponent if present, else stay put.
    if opp_pos != self_pos:
        return step_toward(self_pos, opp_pos)
    return [0, 0]

